@classmethod
def from_function(cls, obj: object) -> Code:
    return cls(getrawcode(obj))

def __lt__(self, other):
    try:
        return self.obj < other.obj
    except TypeError:
        return (str(type(self.obj)), id(self.obj)) < (
            str(type(other.obj)),
            id(other.obj),
        )

def _try_repr_or_str(obj: object) -> str:
    try:
        return repr(obj)
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException:
        return f'{type(obj).__name__}("{obj}")'

def get_terminal_width() -> int:
    width, _ = shutil.get_terminal_size(fallback=(80, 24))

    # The Windows get_terminal_size may be bogus, let's sanify a bit.
    if width < 40:
        width = 80

    return width

def __repr__(self) -> str:
    return "{}.{} {!r}: {} ".format(
        self.__class__.__module__,
        self.__class__.__name__,
        self.__class__.__doc__,
        " ".join(map(str, self.args)),
        # repr(self.args)
    )

def ext(self, arg):
    if not arg.startswith("."):
        arg = "." + arg
    return self.path.ext == arg

def _compare_eq_mapping(
    left: Mapping[object, object],
    right: Mapping[object, object],
    highlighter: _HighlightFunc,
    verbose: int = 0,
    truncation_budget: TruncationBudget = NO_TRUNCATION_BUDGET,
) -> Iterator[str]:
    set_left = set(left)
    set_right = set(right)
    common = set_left.intersection(set_right)
    same = {k: left[k] for k in common if left[k] == right[k]}
    if same and verbose < 2:
        yield f"Omitting {len(same)} identical items, use -vv to show"
    elif same:
        yield "Common items:"
        yield from highlighter(pprint.pformat(same)).splitlines()
